-- C-04 budgets. Preserve the protected purchasing/payment/sales budget_run gateway.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema budget_private;revoke all on schema budget_private from public,anon,authenticated,service_role;grant usage on schema budget_private to authenticated;
create or replace function public.budget_can(p_code text)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform asset_posting_private.identity();return exists(select 1 from public.user_roles ur join public.role_permissions rp using(role_id)join public.permissions p using(permission_id)where ur.user_id=public.app_user_id()and ur.role_id=public.app_active_role_id()and p.code=p_code);exception when insufficient_privilege then return false;end$$;
create function budget_private.matrix(a text,include_lines boolean default false)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select asset_posting_private.allowed('accounting:budgets',a)or(include_lines and asset_posting_private.allowed('accounting:budget-lines',a))$$;
create function budget_private.allowed(code text,a text,include_lines boolean default false)returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select public.budget_can(code)and budget_private.matrix(a,include_lines)$$;
create function budget_private.access(code text,a text,include_lines boolean default false)returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin if not budget_private.allowed(code,a,include_lines)then raise exception using errcode='42501',message='El rol activo no puede realizar esta operación presupuestaria.';end if;return sid;end$$;
create function budget_private.context_access()returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin
 if not(budget_private.allowed('BUDGET_VIEW','view',true)or budget_private.allowed('BUDGET_MANAGE','create')or budget_private.allowed('BUDGET_MANAGE','edit',true)or budget_private.allowed('BUDGET_MANAGE','delete')or budget_private.allowed('BUDGET_APPROVE','edit')or budget_private.allowed('BUDGET_TRANSFER_REQUEST','edit')or budget_private.allowed('BUDGET_OVERRIDE_APPROVE','edit'))then raise exception using errcode='42501',message='Sin acceso al contexto presupuestario.';end if;return sid;end$$;
create or replace function public.budget_access(p_code text)returns bigint language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_code='BUDGET_VIEW'and current_setting('nexo.budget_read_context',true)='true'then return budget_private.context_access();end if;if not public.budget_can(p_code)then raise exception using errcode='42501',message='Falta el permiso técnico del rol activo.';end if;return asset_posting_private.identity();end$$;
do $$declare sig text;f record;body text;names text:='budget_options|budget_save_header_without_categories|budget_save_header|budget_save_lines|budget_header_action_without_delete|budget_header_action|budget_transfer_request|budget_override_action|budget_check_availability|budget_report';begin
 foreach sig in array array['budget_options()','budget_save_header(jsonb)','budget_save_header_without_categories(jsonb)','budget_save_lines(jsonb)','budget_header_action(jsonb)','budget_header_action_without_delete(jsonb)','budget_transfer_request(jsonb)','budget_override_action(jsonb)','budget_check_availability(jsonb)','budget_report(jsonb)','budget_transfer_finish(bigint,text)']loop execute format('alter function public.%s set schema budget_private',sig);end loop;
 for f in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='budget_private'and p.proname~'^budget_'loop body:=pg_get_functiondef(f.oid);body:=regexp_replace(body,'\mpublic\.('||names||')\s*\(','budget_private.\1(','g');body:=regexp_replace(body,'(^|[^[:alnum:]_.])('||names||')\s*\(','\1budget_private.\2(','g');execute body;end loop;
 body:=pg_get_functiondef('budget_private.budget_options()'::regprocedure);body:=replace(body,$n$budget_access('BUDGET_VIEW')$n$,'budget_private.context_access()');execute body;
 -- Explicit account assignment replaces the legacy unassigned-account fallback.
 foreach sig in array array['budget_private.budget_save_header(jsonb)','budget_private.budget_save_lines(jsonb)']loop body:=pg_get_functiondef(sig::regprocedure);body:=replace(body,'or not exists(select 1 from account_subsidiaries where account_id=a.account_id)','');execute body;end loop;
 body:=pg_get_functiondef('budget_private.budget_transfer_finish(bigint,text)'::regprocedure);body:=replace(body,'not exists(select 1 from user_roles where user_id=app_user_id()and role_id in(2,5))',$r$not public.budget_can('BUDGET_APPROVE')$r$);execute body;
end$$;
create function budget_private.lock_scope()returns bigint language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();begin perform pg_advisory_xact_lock(hashtextextended('budget:'||sid,0));return sid;end$$;
create function budget_private.header(id bigint,locking boolean default false)returns public.presupuestos_encabezado language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.presupuestos_encabezado;sid bigint:=asset_posting_private.identity();begin if id is null or id<=0 then raise exception using errcode='22023',message='Presupuesto inválido.';end if;if locking then perform budget_private.lock_scope();select *into h from public.presupuestos_encabezado where presupuestos_encabezado.id=$1 and id_subsidiaria=sid for update;else select *into h from public.presupuestos_encabezado where presupuestos_encabezado.id=$1 and id_subsidiaria=sid;end if;if not found then raise exception using errcode='42501',message='Presupuesto no disponible.';end if;return h;end$$;
create function budget_private.actions(h public.presupuestos_encabezado)returns jsonb language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select jsonb_build_object('canEdit',h.estado='BORRADOR'and budget_private.allowed('BUDGET_MANAGE','edit',true),'canEditHeader',h.estado='BORRADOR'and budget_private.allowed('BUDGET_MANAGE','edit'),'canDelete',h.estado='BORRADOR'and budget_private.allowed('BUDGET_MANAGE','delete'),'canCopy',budget_private.allowed('BUDGET_MANAGE','create'),'canApprove',h.estado='BORRADOR'and budget_private.allowed('BUDGET_APPROVE','edit'),'canClose',h.estado='APROBADO'and budget_private.allowed('BUDGET_APPROVE','edit'),'canTransfer',h.estado='APROBADO'and budget_private.allowed('BUDGET_TRANSFER_REQUEST','edit'))$$;
create function public.budget_options()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=budget_private.context_access();result jsonb;begin result:=budget_private.budget_options();return result||jsonb_build_object('permissions',jsonb_build_object('view',budget_private.allowed('BUDGET_VIEW','view',true),'manage',budget_private.allowed('BUDGET_MANAGE','edit',true),'canCreate',budget_private.allowed('BUDGET_MANAGE','create'),'approve',budget_private.allowed('BUDGET_APPROVE','edit'),'transfer',budget_private.allowed('BUDGET_TRANSFER_REQUEST','edit'),'override',budget_private.allowed('BUDGET_OVERRIDE_APPROVE','edit')),'accounts',coalesce((select jsonb_agg(jsonb_build_object('id',a.account_id,'number',a.account_number,'name',a.account_name,'category',a.category)order by a.account_number)from public.chart_accounts a join public.account_subsidiaries s using(account_id)where s.subsidiary_id=sid and s.is_active and a.category in('Ingreso','Costo','Gasto')and a.accepts_entries and not a.is_inactive),'[]'::jsonb));end$$;
create function public.budget_save_header(p jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.presupuestos_encabezado;begin perform budget_private.access('BUDGET_MANAGE',case when nullif(p->>'id','')is null then'create'else'edit'end);perform budget_private.lock_scope();if nullif(p->>'id','')is not null then h:=budget_private.header((p->>'id')::bigint,true);end if;return budget_private.budget_save_header(p);end$$;
create function public.budget_save_lines(p jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.presupuestos_encabezado;item jsonb;amount numeric;begin perform budget_private.access('BUDGET_MANAGE','edit',true);h:=budget_private.header((p->>'id')::bigint,true);
 if jsonb_typeof(p->'lines')is distinct from'array'or jsonb_array_length(p->'lines')>12000 then raise exception using errcode='22023',message='Matriz inválida o demasiado grande.';end if;
 for item in select value from jsonb_array_elements(p->'lines')loop amount:=(item->>'amount')::numeric;if not asset_posting_private.finite(amount)or amount<0 then raise exception using errcode='22023',message='El monto debe ser finito y no negativo.';end if;end loop;return budget_private.budget_save_lines(p);end$$;
create function public.budget_header_action(p jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare h public.presupuestos_encabezado;factor numeric;begin
 if p->>'action'='copy'then perform budget_private.access('BUDGET_MANAGE','create');factor:=coalesce((p->>'percent')::numeric,0);if not asset_posting_private.finite(factor)then raise exception using errcode='22023',message='Porcentaje inválido.';end if;
 elsif p->>'action'='delete'then perform budget_private.access('BUDGET_MANAGE','delete');elsif p->>'action'in('approve','close')then perform budget_private.access('BUDGET_APPROVE','edit');else raise exception using errcode='22023',message='Acción inválida.';end if;
 h:=budget_private.header((p->>'id')::bigint,true);if p->>'action'in('approve','close','delete')and h.revision is distinct from(p->>'revision')::integer then raise exception using errcode='55000',message='La versión cambió; revise nuevamente el presupuesto.';end if;
 if p->>'action'='approve'and exists(select 1 from public.presupuestos_lineas l where l.id_presupuesto_encabezado=h.id and(not exists(select 1 from public.chart_accounts a join public.account_subsidiaries s using(account_id)where a.account_id=l.id_cuenta_contable and s.subsidiary_id=h.id_subsidiaria and s.is_active and a.accepts_entries and not a.is_inactive and a.category=any(h.categorias))or not asset_posting_private.finite(l.monto_presupuestado)or not asset_posting_private.finite(l.monto_modificaciones)))then raise exception using errcode='55000',message='Las cuentas o importes cambiaron desde la revisión.';end if;return budget_private.budget_header_action(p);end$$;
create function budget_private.transfer(id bigint)returns public.presupuestos_modificaciones language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare m public.presupuestos_modificaciones;begin select *into m from public.presupuestos_modificaciones where presupuestos_modificaciones.id=$1 and id_subsidiaria=asset_posting_private.identity();if not found then raise exception using errcode='42501',message='Modificación no disponible.';end if;return m;end$$;
create function budget_private.transfer_fingerprint(id bigint)returns text language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select md5(jsonb_build_array(m.id,m.id_subsidiaria,m.tipo_modificacion,m.motivo_justificacion,m.id_linea_origen,m.id_linea_destino,m.monto_solicitado)::text)from public.presupuestos_modificaciones m where m.id=$1$$;
create function public.budget_transfer_request(p jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=budget_private.access('BUDGET_TRANSFER_REQUEST','edit');amount numeric:=(p->>'amount')::numeric;begin perform budget_private.lock_scope();if not asset_posting_private.finite(amount)or amount<=0 or coalesce(p->>'type','')not in('TRASLADO','ADICION','REDUCCION')then raise exception using errcode='22023',message='Modificación o monto inválidos.';end if;
 if not exists(select 1 from public.wf_workflows w join public.wf_rules r on r.workflow_id=w.id where w.subsidiaria_id=sid and w.entity_type='BUDGET_TRANSFER'and w.estado_activo)then raise exception using errcode='55000',message='Configure el workflow financiero y sus aprobadores antes de solicitar una modificación.';end if;return budget_private.budget_transfer_request(p);end$$;
create function public.budget_override_action(p jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p->>'action'='apply'then perform budget_private.access('BUDGET_VIEW','view',true);elsif p->>'action'in('approve','reject')then perform budget_private.access('BUDGET_OVERRIDE_APPROVE','edit');else raise exception using errcode='22023',message='Acción inválida.';end if;perform budget_private.lock_scope();return budget_private.budget_override_action(p);end$$;
create function public.budget_check_availability(p jsonb)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare amount numeric:=(p->>'monto')::numeric;sid bigint:=budget_private.access('BUDGET_VIEW','view',true);begin if not asset_posting_private.finite(amount)or amount<0 then raise exception using errcode='22023',message='Importe inválido.';end if;if(p->>'id_subsidiaria')::bigint is distinct from sid then raise exception using errcode='42501',message='Filial no disponible.';end if;return budget_private.budget_check_availability(p);end$$;
create function public.budget_report(p jsonb default'{}')returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=budget_private.context_access();h public.presupuestos_encabezado;result jsonb;prior text:=current_setting('nexo.budget_read_context',true);begin h:=budget_private.header((p->>'id')::bigint);perform set_config('nexo.budget_read_context','true',true);result:=budget_private.budget_report(p);perform set_config('nexo.budget_read_context',coalesce(prior,''),true);
 return result||jsonb_build_object('actions',budget_private.actions(h),'overrides',coalesce((select jsonb_agg(x||jsonb_build_object('canApprove',x->>'status'='PENDIENTE'and(x->>'requested_by')::bigint<>public.app_user_id()and budget_private.allowed('BUDGET_OVERRIDE_APPROVE','edit'),'canApply',x->>'status'='APROBADO'and(x->>'requested_by')::bigint=public.app_user_id()and budget_private.allowed('BUDGET_VIEW','view',true)))from jsonb_array_elements(coalesce(result->'overrides','[]'::jsonb))x where(x->>'requested_by')::bigint=public.app_user_id()or budget_private.allowed('BUDGET_OVERRIDE_APPROVE','edit')),'[]'::jsonb));
 exception when others then perform set_config('nexo.budget_read_context',coalesce(prior,''),true);raise;end$$;

-- Preserve the previous sales/purchase/payment wrappers and constrain only budget transfer workflow.
alter function public.wf_start_entity(text,bigint,jsonb)set schema budget_private;
alter function public.wf_act(bigint,text,text,inet)set schema budget_private;
alter function public.wf_instance_detail(text,bigint)set schema budget_private;
create function public.wf_start_entity(p_entity_type text,p_entity_id bigint,p_context jsonb default'{}')returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare m public.presupuestos_modificaciones;r jsonb;prior text:=current_setting('nexo.budget_transfer_submit',true);begin if p_entity_type='BUDGET_TRANSFER'then perform budget_private.access('BUDGET_TRANSFER_REQUEST','edit');perform budget_private.lock_scope();m:=budget_private.transfer(p_entity_id);if m.estado_workflow not in('BORRADOR','PENDIENTE_APROBACION')or exists(select 1 from public.wf_instances where entity_type=p_entity_type and entity_id=p_entity_id)then raise exception using errcode='55000',message='La modificación conserva su historial de aprobación.';end if;p_context:=jsonb_build_object('budgetFingerprint',budget_private.transfer_fingerprint(m.id));perform set_config('nexo.budget_transfer_submit',m.id::text,true);end if;r:=budget_private.wf_start_entity(p_entity_type,p_entity_id,p_context);if p_entity_type='BUDGET_TRANSFER'and not exists(select 1 from public.wf_instance_steps where instance_id=(r->>'id')::bigint)then raise exception using errcode='55000',message='No existen niveles de aprobación aplicables.';end if;perform set_config('nexo.budget_transfer_submit',coalesce(prior,''),true);return r;exception when others then perform set_config('nexo.budget_transfer_submit',coalesce(prior,''),true);raise;end$$;
create function public.wf_act(p_instance_id bigint,p_action text,p_comment text default null,p_ip inet default null)returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare i public.wf_instances;m public.presupuestos_modificaciones;r jsonb;prior text:=current_setting('nexo.budget_transfer_vote',true);begin perform asset_posting_private.identity();select *into i from public.wf_instances where id=p_instance_id;
 if i.entity_type='BUDGET_TRANSFER'then perform budget_private.lock_scope();select *into i from public.wf_instances where id=p_instance_id for update;m:=budget_private.transfer(i.entity_id);if i.amount is distinct from m.monto_solicitado or i.subsidiaria_id<>m.id_subsidiaria or i.status<>'EN_REVISION'or i.approval_context->>'budgetFingerprint' is distinct from budget_private.transfer_fingerprint(m.id)then raise exception using errcode='55000',message='La modificación o su aprobación cambiaron.';end if;
 if upper(p_action)='CANCELAR'then perform budget_private.access('BUDGET_TRANSFER_REQUEST','edit');if i.requested_by<>public.app_user_id()then raise exception using errcode='42501',message='Solo el solicitante puede cancelar.';end if;
 elsif upper(p_action)in('APROBAR','RECHAZAR')then perform budget_private.access('BUDGET_APPROVE','edit');if not exists(select 1 from public.wf_instance_steps s where s.instance_id=i.id and s.nivel=i.current_level and s.status='PENDIENTE'and(s.usuario_aprobador_id=public.app_user_id()or s.rol_aprobador_id=public.app_active_role_id()))then raise exception using errcode='42501',message='El rol activo no está asignado al nivel pendiente.';end if;else raise exception using errcode='22023',message='Acción inválida.';end if;
 if upper(p_action)in('RECHAZAR','CANCELAR')and nullif(trim(p_comment),'')is null then raise exception using errcode='22023',message='Indique el motivo.';end if;perform set_config('nexo.budget_transfer_vote',m.id::text,true);end if;
 r:=budget_private.wf_act(p_instance_id,p_action,p_comment,p_ip);perform set_config('nexo.budget_transfer_vote',coalesce(prior,''),true);return r;
 exception when others then perform set_config('nexo.budget_transfer_vote',coalesce(prior,''),true);raise;end$$;
create function public.budget_transfer_finish(p_id bigint,p_status text)returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_status='PENDIENTE_APROBACION'and current_setting('nexo.budget_transfer_submit',true)=p_id::text and exists(select 1 from public.wf_instances where entity_type='BUDGET_TRANSFER'and entity_id=p_id and requested_by=public.app_user_id()and subsidiaria_id=asset_posting_private.identity()and status='EN_REVISION')then perform budget_private.budget_transfer_finish(p_id,p_status);return;end if;if current_setting('nexo.budget_transfer_vote',true)is distinct from p_id::text or not exists(select 1 from public.wf_instances where entity_type='BUDGET_TRANSFER'and entity_id=p_id and subsidiaria_id=asset_posting_private.identity()and status=p_status)then raise exception using errcode='42501',message='Las modificaciones se aplican desde su aprobación asignada.';end if;perform budget_private.budget_transfer_finish(p_id,p_status);end$$;
create function public.wf_instance_detail(p_entity_type text,p_entity_id bigint)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin if p_entity_type='BUDGET_TRANSFER'then perform budget_private.context_access();perform budget_private.transfer(p_entity_id);end if;return budget_private.wf_instance_detail(p_entity_type,p_entity_id);end$$;
create function budget_private.visible(sid bigint)returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin return sid=budget_private.context_access();exception when insufficient_privilege then return false;end$$;
do $$declare t text;p record;c record;pred text;f record;body text;needle text:='and i.subsidiaria_id=active_subsidiary_id()';begin
 foreach t in array array['presupuestos_encabezado','presupuestos_lineas','presupuestos_modificaciones','budget_overrides','budget_events','budget','budget_line']loop
 execute format('alter table public.%I enable row level security',t);for p in select policyname from pg_policies where schemaname='public'and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;
 pred:=case t when'presupuestos_encabezado'then'budget_private.visible(id_subsidiaria)'when'presupuestos_lineas'then'exists(select 1 from public.presupuestos_encabezado h where h.id=id_presupuesto_encabezado and budget_private.visible(h.id_subsidiaria))'when'presupuestos_modificaciones'then'budget_private.visible(id_subsidiaria)'when'budget_line'then'exists(select 1 from public.budget b where b.budget_id=budget_line.budget_id and budget_private.visible(b.subsidiary_id))'when'budget_overrides'then'budget_private.visible(subsidiary_id)and(requested_by=public.app_user_id()or budget_private.allowed(''BUDGET_OVERRIDE_APPROVE'',''edit''))'else'budget_private.visible(subsidiary_id)'end;
 execute format('create policy budget_secure_read on public.%I for select to authenticated using(%s)',t,pred);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);for c in select column_name from information_schema.columns where table_schema='public'and table_name=t loop execute format('revoke insert(%I),update(%I),select(%I),references(%I)on public.%I from public,anon,authenticated,service_role',c.column_name,c.column_name,c.column_name,c.column_name,t);end loop;execute format('grant select on public.%I to authenticated',t);
 end loop;
 for f in select pf.oid::regprocedure signature from pg_proc pf join pg_namespace n on n.oid=pf.pronamespace where n.nspname='public'and pf.proname like'budget_%'and pf.prorettype<>'trigger'::regtype loop execute format('revoke all on function %s from public,anon,authenticated,service_role',f.signature);end loop;
 body:=pg_get_functiondef('public.wf_inbox()'::regprocedure);if strpos(body,needle)=0 then raise exception 'Unexpected workflow inbox';end if;body:=replace(body,needle,'and(i.entity_type<>''BUDGET_TRANSFER''or(budget_private.visible(i.subsidiaria_id)and(s.usuario_aprobador_id=public.app_user_id()or s.rol_aprobador_id=public.app_active_role_id()))) '||needle);execute body;
end$$;
revoke all on all functions in schema budget_private from public,anon,authenticated,service_role;grant execute on function budget_private.visible(bigint),budget_private.allowed(text,text,boolean)to authenticated;
revoke all on function public.wf_start_entity(text,bigint,jsonb),public.wf_act(bigint,text,text,inet),public.wf_instance_detail(text,bigint)from public,anon,authenticated,service_role;
grant execute on function public.budget_options(),public.budget_save_header(jsonb),public.budget_save_lines(jsonb),public.budget_header_action(jsonb),public.budget_transfer_request(jsonb),public.budget_override_action(jsonb),public.budget_check_availability(jsonb),public.budget_report(jsonb),public.wf_start_entity(text,bigint,jsonb),public.wf_act(bigint,text,text,inet),public.wf_instance_detail(text,bigint)to authenticated;
notify pgrst,'reload schema';
